import { Injectable, NestMiddleware } from '@nestjs/common';
import { Request, Response, NextFunction } from 'express';

/**
 * Middleware to propagate request ID back to the client via response header.
 * The request ID is generated by pino-http (genReqId) and stored in req.id.
 * This allows frontend/support to reference a specific request when reporting issues.
 */
@Injectable()
export class RequestIdMiddleware implements NestMiddleware {
	use(req: Request, res: Response, next: NextFunction) {
		// pino-http sets req.id; we propagate it to the response header
		if (req.id) {
			res.setHeader('x-request-id', req.id as string);
		}
		next();
	}
}
